import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, spring } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CountingTimelineProps = Record<string, any>;

const CountingTimeline: React.FC<CountingTimelineProps> = ({
  backgroundColor = "#080a0f",
  transparentBackground = false,
  durationInSeconds = 8,
  startYear = 2024,
  endYear = -476,
  timelineColor = "#2a3245",
  textColor = "#ffffff",
  accentColor = "#fbbf24",
  titleText = "JOURNEY THROUGH TIME",
  showEpoch = true,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Space Grotesk", "Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety checks for parser and transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Animation Timing calculations
  const durationFrames = durationInSeconds * fps;
  const animStart = Math.max(1, Math.round(durationFrames * 0.15));
  const animEnd = Math.max(animStart + 1, Math.round(durationFrames * 0.85));

  // Progress of the time travel (0 to 1)
  const progress = interpolate(frame, [animStart, animEnd], [0, 1], {
    easing: Easing.bezier(0.65, 0, 0.35, 1),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Calculate the currently displayed year
  const currentYearVal = interpolate(progress, [0, 1], [startYear, endYear]);
  const displayYear = Math.max(1, Math.abs(Math.round(currentYearVal)));
  const isBCE = currentYearVal < 0;
  const epochStr = isBCE ? "BCE" : "CE";

  // Visual effects tied to the speed of time travel
  const travelIntensity = Math.sin(progress * Math.PI); // 0 at start/end, 1 in the middle
  const motionBlur = travelIntensity * 8; // Max 8px blur
  const scaleEffect = 1 + travelIntensity * 0.05;

  // Title Animation
  const titleOpacity = interpolate(frame, [0, fps], [0, 1], { extrapolateRight: "clamp" });
  const titleY = spring({ frame, fps, config: { damping: 12 } });
  const mappedTitleY = interpolate(titleY, [0, 1], [-50, height * 0.15]);

  // Generate Timeline Ticks
  const numTicks = 30;
  const tickSpacing = height / 15;
  const totalTickArea = tickSpacing * numTicks;
  const timelineOffset = interpolate(progress, [0, 1], [0, height * 15]); // Move down rapidly

  const ticks = useMemo(() => {
    return Array.from({ length: numTicks }).map((_, i) => i);
  }, [numTicks]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden", transition: "none" }}>
      
      {/* Background Timeline Grid Elements */}
      <AbsoluteFill style={{ left: "15%", width: "2px", backgroundColor: timelineColor, opacity: 0.5, transition: "none" }} />
      
      <AbsoluteFill style={{ transition: "none" }}>
        {ticks.map((i) => {
          // Calculate wrapping Y position to create endless loop effect
          const rawY = i * tickSpacing + timelineOffset;
          const wrappedY = (rawY % totalTickArea) - tickSpacing;
          
          // Determine if it's a major or minor tick
          const isMajor = i % 5 === 0;
          const tickWidth = isMajor ? width * 0.08 : width * 0.03;
          const tickOpacity = isMajor ? 0.8 : 0.4;
          
          // Apply motion blur to ticks when moving fast
          const tickStyle: React.CSSProperties = {
            position: "absolute",
            left: "15%",
            top: 0,
            width: tickWidth,
            height: isMajor ? "2px" : "1px",
            backgroundColor: timelineColor,
            opacity: tickOpacity,
            transform: `translateY(${wrappedY}px)`,
            filter: `blur(${motionBlur}px)`,
            transition: "none",
          };

          return <div key={i} style={tickStyle} />;
        })}
      </AbsoluteFill>

      {/* Main Content Area */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        {/* Animated Title */}
        <AbsoluteFill style={{ transition: "none" }}>
          <h2
            style={{
              position: "absolute",
              width: "100%",
              textAlign: "center",
              top: 0,
              margin: 0,
              fontSize: 32,
              letterSpacing: "0.2em",
              fontWeight: 600,
              color: textColor,
              opacity: titleOpacity,
              transform: `translateY(${mappedTitleY}px)`,
              transition: "none",
            }}
          >
            {titleText}
          </h2>
        </AbsoluteFill>

        {/* Central Counter */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            transform: `scale(${scaleEffect})`,
            transition: "none",
          }}
        >
          <div
            style={{
              fontFamily: "Space Grotesk",
              fontSize: 220,
              fontWeight: 700,
              color: textColor,
              lineHeight: 1,
              fontVariantNumeric: "tabular-nums",
              textShadow: `0 0 ${travelIntensity * 40}px ${accentColor}40`,
              transition: "none",
            }}
          >
            {displayYear}
          </div>
          
          {showEpoch && (
            <div
              style={{
                fontSize: 48,
                fontWeight: 600,
                color: accentColor,
                letterSpacing: "0.1em",
                marginTop: 10,
                opacity: 0.9,
                transition: "none",
              }}
            >
              {epochStr}
            </div>
          )}
        </div>
      </AbsoluteFill>

      {/* Atmospheric Vignette Overlay */}
      <AbsoluteFill
        style={{
          boxShadow: `inset 0 0 ${height * 0.2}px rgba(0,0,0,0.6)`,
          pointerEvents: "none",
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default CountingTimeline;